import { cookies } from 'next/headers';
import { createCookieApiServer } from '@ringee/frontend-shared/lib/api.server';
import { readAuthPrincipal } from '@ringee/frontend-shared/lib/auth.contracts';

/** Request-scoped only: identity is verified by the backend, not cookie presence. */
export async function getAuthPrincipal() {
  const cookieStore = await cookies();
  return readAuthPrincipal(createCookieApiServer(cookieStore.toString()));
}

