'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { useSearchParams } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { ApiError } from '@ringee/frontend-shared/lib/api';
import { Button } from '@ringee/frontend-shared/components/ui/button';
import { Form } from '@ringee/frontend-shared/components/ui/form';
import { FormInput } from '@ringee/frontend-shared/components/forms/form-input';
import {
  createRingeeAuthClient,
  signInDestination
} from '@ringee/frontend-shared/lib/auth.client';

// Dormant until the provider, protected routes, phone onboarding and all
// consumers are migrated together. The live sign-in-view still uses Clerk.
type UserFormValue = { email: string; password: string };

export default function UserAuthForm() {
  const t = useTranslations('auth');
  const searchParams = useSearchParams();
  const formSchema = z.object({
    email: z.string().email({ message: t('errors.invalidEmail') }),
    password: z.string().min(1, { message: t('errors.passwordRequired') })
  });
  const form = useForm<UserFormValue>({
    resolver: zodResolver(formSchema),
    defaultValues: { email: '', password: '' }
  });

  const onSubmit = async (credentials: UserFormValue) => {
    form.clearErrors('root');
    try {
      const apiURL = process.env.NEXT_PUBLIC_API_URL;
      if (!apiURL) throw new Error('Authentication API is not configured');
      const client = createRingeeAuthClient(apiURL);
      const principal = await client.signIn(credentials);
      form.resetField('password');
      // A document navigation clears cached data from the previous session.
      window.location.assign(
        signInDestination(principal, searchParams.get('callbackUrl'))
      );
    } catch (error) {
      form.resetField('password');
      const invalidCredentials = error instanceof ApiError && error.status === 401;
      form.setError('root', {
        message: t(invalidCredentials ? 'errors.invalidCredentials' : 'errors.signInUnavailable')
      });
    }
  };

  return (
    <Form
      form={form}
      onSubmit={form.handleSubmit(onSubmit)}
      className='w-full space-y-4'
    >
      <FormInput
        control={form.control}
        name='email'
        type='email'
        label={t('fields.email')}
        placeholder={t('fields.emailPlaceholder')}
        disabled={form.formState.isSubmitting}
      />
      <FormInput
        control={form.control}
        name='password'
        type='password'
        label={t('fields.password')}
        placeholder={t('fields.passwordPlaceholder')}
        disabled={form.formState.isSubmitting}
      />
      {form.formState.errors.root?.message && (
        <p role='alert' className='text-destructive text-sm'>
          {form.formState.errors.root.message}
        </p>
      )}
      <Button
        type='submit'
        className='w-full'
        disabled={form.formState.isSubmitting}
      >
        {t('signIn.submit')}
      </Button>
    </Form>
  );
}

